import{c as d,Q as r,j as a,m as e}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"内置数据类型","description":"","frontmatter":{},"headers":[{"level":1,"title":"内置数据类型","slug":"内置数据类型"},{"level":2,"title":"标量类型","slug":"标量类型"},{"level":2,"title":"短向量类型","slug":"短向量类型"},{"level":2,"title":"dim3","slug":"dim3"}],"relativePath":"api/SIMT-API/SIMT编程简介/扩展语法/内置数据类型-139.md","filePath":"api/SIMT-API/SIMT编程简介/扩展语法/内置数据类型-139.md"}'),i={name:"api/SIMT-API/SIMT编程简介/扩展语法/内置数据类型-139.md"};function n(l,t,o,s,h,p){return r(),a("div",null,[...t[0]||(t[0]=[e(`<h1 id="内置数据类型" tabindex="-1">内置数据类型 <a class="header-anchor" href="#内置数据类型" aria-label="Permalink to &quot;内置数据类型&quot;">​</a></h1><p>SIMT编程提供了一系列适用于Device侧的数据类型，包括标量、短向量以及dim3结构体。</p><h2 id="标量类型" tabindex="-1">标量类型 <a class="header-anchor" href="#标量类型" aria-label="Permalink to &quot;标量类型&quot;">​</a></h2><p>标量数据类型覆盖布尔型（bool）、整型（uint8/int8到uint64/int64）、浮点型（float8_e4m3、float8_e5m2、hifloat8、half、bfloat16、float）。</p><p><strong>表 1</strong> 标量数据类型</p><table tabindex="0"><thead><tr><th>类型</th><th>数据类型</th><th>描述</th><th>Size（bit）</th><th>取值范围</th></tr></thead><tbody><tr><td>布尔型</td><td>bool</td><td>全0代表false，否则代表true。</td><td>8</td><td>true, false</td></tr><tr><td>整形</td><td>uint8_t</td><td>unsigned char</td><td>8</td><td>[0, 255]</td></tr><tr><td>整形</td><td>int8_t</td><td>signed char</td><td>8</td><td>[-128, 127]</td></tr><tr><td>整形</td><td>uint16_t</td><td>unsigned short</td><td>16</td><td>[0, 65535]</td></tr><tr><td>整形</td><td>int16_t</td><td>signed short</td><td>16</td><td>[-32768, 32767]</td></tr><tr><td>整形</td><td>uint32_t</td><td>unsigned int</td><td>32</td><td>[0, 4294967295]</td></tr><tr><td>整形</td><td>int32_t</td><td>signed int</td><td>32</td><td>[-2147483648, 2147483647]</td></tr><tr><td>整形</td><td>uint64_t</td><td>unsigned long</td><td>64</td><td>[0,18446744073709551615]</td></tr><tr><td>整形</td><td>int64_t</td><td>signed long</td><td>64</td><td>[-9223372036854775808, 9223372036854775807]</td></tr><tr><td>浮点型</td><td>float8_e4m3_t</td><td>符号位宽1，指数位宽4，尾数位宽3</td><td>8</td><td>[26 - 29, 29 - 26]</td></tr><tr><td>浮点型</td><td>float8_e5m2_t</td><td>符号位宽1，指数位宽5，尾数位宽2</td><td>8</td><td>[213 - 216, 216 - 213]</td></tr><tr><td>浮点型</td><td>hifloat8_t</td><td>符号位宽1，点域位宽2，指数与尾数位宽由点域编码决定</td><td>8</td><td>点域编码决定数据精度与取值范围</td></tr><tr><td>浮点型</td><td>half</td><td>符号位宽1，指数位宽5，尾数位宽10</td><td>16</td><td>[25 - 216, 216 - 25]</td></tr><tr><td>浮点型</td><td>bfloat16_t</td><td>符号位宽1，指数位宽8，尾数位宽7</td><td>16</td><td>[2120 - 2128, 2128 - 2120]</td></tr><tr><td>浮点型</td><td>float</td><td>符号位宽1，指数位宽8，尾数位宽23</td><td>32</td><td>[2104 - 2128, 2128 - 2104]</td></tr></tbody></table><h2 id="短向量类型" tabindex="-1">短向量类型 <a class="header-anchor" href="#短向量类型" aria-label="Permalink to &quot;短向量类型&quot;">​</a></h2><p>短向量类型是一种在SIMT编程模型中提供的固定长度向量类型，用于简化向量数据的表示和操作。该类型适用于处理包含多个分量的数据，如坐标、颜色、向量运算等。</p><ul><li><p>内存特点：</p><p>紧凑存储：短向量类型在内存中连续存储，无填充 。</p><p>对齐要求：遵循自然对齐原则，提升访问效率。</p><p>跨线程共享：可存储在Unified Buffer中供线程块内共享 。</p><p>直接内存访问：支持直接从Global Memory加载和存储。</p></li><li><p>应用场景：</p><p>颜色处理：RGB/RGBA颜色值的操作。</p><p>向量运算：物理模拟、图形渲染中的向量计算。</p><p>数据打包：将多个相关值打包处理。</p><p>内存访问优化：通过向量化提升内存带宽利用率。</p></li><li><p>短向量变量访问：</p><p>变量通过.x、.y、.z、.w的方式进行访问。</p></li></ul><p>当前已支持的短向量数据类型如下：</p><p><strong>表 2</strong> 短向量数据类型</p><table tabindex="0"><thead><tr><th>元素数据类型</th><th>Vector X2</th><th>Vector X4</th></tr></thead><tbody><tr><td>unsigned char</td><td>uchar2</td><td>uchar4</td></tr><tr><td>signed char</td><td>char2</td><td>char4</td></tr><tr><td>unsigned short (16bit)</td><td>ushort2</td><td>ushort4</td></tr><tr><td>signed short (16bit)</td><td>short2</td><td>short4</td></tr><tr><td>unsigned int</td><td>uint2</td><td>uint4</td></tr><tr><td>signed int</td><td>int2</td><td>int4</td></tr><tr><td>无符号的长整型 (64bit)</td><td>ulonglong2</td><td>ulonglong4</td></tr><tr><td>有符号的长整型 (64bit)</td><td>longlong2</td><td>longlong4</td></tr><tr><td>无符号的长整型 (32bit)</td><td>ulong2</td><td>ulong4</td></tr><tr><td>有符号的长整型 (32bit)</td><td>long2</td><td>long4</td></tr><tr><td>浮点型，1符号位，2指数位，1尾数位</td><td>float4_e2m1x2_t</td><td>-</td></tr><tr><td>浮点型，1符号位，1指数位，2尾数位</td><td>float4_e1m2x2_t</td><td>-</td></tr><tr><td>浮点型，1符号位，4指数位，3尾数位</td><td>float8_e4m3x2_t</td><td>-</td></tr><tr><td>浮点型，1符号位，5指数位，2尾数位</td><td>float8_e5m2x2_t</td><td>-</td></tr><tr><td>浮点型 hif8</td><td>hifloat8x2_t</td><td>-</td></tr><tr><td>浮点型，1符号位，5指数位，10尾数位</td><td>half2</td><td>-</td></tr><tr><td>浮点型，1符号位，8指数位，7尾数位</td><td>bfloat16x2_t</td><td>-</td></tr><tr><td>浮点型，1符号位，8指数位，23尾数位</td><td>float2</td><td>float4</td></tr></tbody></table><p>每种短向量的内存大小与地址对齐大小如下：</p><p><strong>表 3</strong> 短向量数据类型内存大小</p><table tabindex="0"><thead><tr><th>数据类型</th><th>内存大小（字节）</th><th>地址对齐（字节）</th></tr></thead><tbody><tr><td>char2, uchar2</td><td>2</td><td>2</td></tr><tr><td>char4, uchar4</td><td>4</td><td>4</td></tr><tr><td>short2, ushort2</td><td>4</td><td>4</td></tr><tr><td>short4, ushort4</td><td>8</td><td>8</td></tr><tr><td>int2, uint2</td><td>8</td><td>8</td></tr><tr><td>int4, uint4</td><td>16</td><td>16</td></tr><tr><td>long2, ulong2</td><td>8</td><td>8</td></tr><tr><td>long4, ulong4</td><td>16</td><td>16</td></tr><tr><td>longlong2, ulonglong2</td><td>16</td><td>16</td></tr><tr><td>longlong4, ulonglong4</td><td>32</td><td>32</td></tr><tr><td>float2</td><td>8</td><td>8</td></tr><tr><td>float4</td><td>16</td><td>16</td></tr><tr><td>float4_e2m1x2_t, float4_e1m2x2_t</td><td>1</td><td>1</td></tr><tr><td>float8_e4m3x2_t, float8_e5m2x2_t, hifloat8x2_t</td><td>2</td><td>2</td></tr><tr><td>half2, bfloat16x2_t</td><td>4</td><td>4</td></tr></tbody></table><h2 id="dim3" tabindex="-1">dim3 <a class="header-anchor" href="#dim3" aria-label="Permalink to &quot;dim3&quot;">​</a></h2><p>用于指定和获取线程网格（Grid）、线程块（Thread Block）在x、y、z维度上的内置结构体。</p><p>dim3由3个无符号整数组成，结构体定义为{dimx，dimy，dimz}，用于指定3个不同维度的大小，三维总数为dimx * dimy * dimz。开发者可以通过如下方式创建dim3结构。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dim3(x); // 创建一维结构，dimy和dimz为默认值1</span></span>
<span class="line"><span>dim3(x, y); // 创建二维结构，dimz为默认值1</span></span>
<span class="line"><span>dim3(x, y, z); // 创建三维结构</span></span></code></pre></div>`,19)])])}const g=d(i,[["render",n]]);export{u as __pageData,g as default};
